#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s1, s2;
    cin >> s1 >> s2;

    int target = 0, current = 0, unknown = 0;

    for (char c : s1)
        target += (c == '+') ? 1 : -1;

    for (char c : s2) {
        if (c == '+') ++current;
        else if (c == '-') --current;
        else ++unknown;
    }

    int needed = target - current;
    long double probability = 0.0L;

    if (abs(needed) <= unknown && (unknown + needed) % 2 == 0) {
        int plusNeeded = (unknown + needed) / 2;
        long double combinations = 1.0L;

        for (int i = 1; i <= plusNeeded; ++i)
            combinations *= static_cast<long double>(unknown - i + 1) / i;

        probability = combinations / powl(2.0L, unknown);
    }

    cout << fixed << setprecision(11) << probability;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    string s1, s2;
    cin >> s1 >> s2;

    int target = 0, current = 0, unknown = 0;

    for (char c : s1)
        target += (c == '+') ? 1 : -1;

    for (char c : s2) {
        if (c == '+') ++current;
        else if (c == '-') --current;
        else ++unknown;
    }

    vector<long double> dp(2 * unknown + 1, 0.0L);
    dp[unknown] = 1.0L;

    for (int i = 0; i < unknown; ++i) {
        vector<long double> next(2 * unknown + 1, 0.0L);
        for (int j = 0; j <= 2 * unknown; ++j) {
            if (dp[j] == 0.0L) continue;
            if (j > 0) next[j - 1] += dp[j] / 2.0L;
            if (j < 2 * unknown) next[j + 1] += dp[j] / 2.0L;
        }
        dp.swap(next);
    }

    int index = unknown + target - current;
    long double answer = (index >= 0 && index <= 2 * unknown) ? dp[index] : 0.0L;

    cout << fixed << setprecision(11) << answer;
    return 0;
}

