    string s1, s2;
    cin >> s1 >> s2;

    int target = 0, current = 0, unknown = 0;

    for (char c : s1)
        target += (c == '+') ? 1 : -1;

    for (char c : s2) {
        if (c == '+') ++current;
        else if (c == '-') --current;
        else ++unknown;
    }

    int value = target - current + unknown;
    long double probability = 0.0L;

    if (value % 2 == 0) {
        int plusNeeded = value / 2;
        if (plusNeeded >= 0 && plusNeeded <= unknown) {
            long double combinations = 1.0L;
            plusNeeded = min(plusNeeded, unknown - plusNeeded);

            for (int i = 1; i <= plusNeeded; ++i)
                combinations *= static_cast<long double>(unknown - plusNeeded + i) / i;

            probability = ldexpl(combinations, -unknown);
        }
    }

    cout << fixed << setprecision(11) << probability;
    return 0;
}

